<section class="section-heading"><div><h2>Your design history</h2><p>Restoring creates a new entry. Thumbnails show saved palette/layout summaries, not old website screenshots.</p></div></section><form method="post" class="studio-panel"><?php $hidden('history_limit')?><label>History entries to keep (10–200)<input type="number" name="limit" min="10" max="200" value="<?=$state['historyLimit']?>"></label><button>Set retention limit</button></form><div class="theme-grid"><?php foreach(ag_sd_history_list() as $entry):$primary='public';foreach($entry['scopes'] as $candidate)if(isset(ag_sd_scopes()[$candidate])){$primary=$candidate;break;}$theme=ag_sd_active_theme($entry['after'],$primary);?><article class="theme-card"><div class="theme-picture"><?=ag_sd_thumbnail($theme,$entry['label'])?></div><div class="theme-copy"><?php if(ag_sa_revision($state)===ag_sa_revision($entry['after'])):?><span class="active-badge">CURRENT DESIGN</span><?php endif ?><h3><?=ag_h($entry['label'])?></h3><time datetime="<?=gmdate('c',(int)$entry['timestamp'])?>"><?=gmdate('Y-m-d H:i',(int)$entry['timestamp'])?> UTC</time><p><?=ag_h(implode(', ',$entry['scopes']))?></p><button type="button" class="secondary preview-design" data-url="<?=$primary==='public'?'/Other/site-front-preview.php?history=':'/Other/site-theme-preview.php?history='?><?=ag_h($entry['id'])?>&amp;scope=<?=ag_h($primary)?>">Preview</button><form method="post"><?php $hidden('history_restore')?><input type="hidden" name="historyId" value="<?=ag_h($entry['id'])?>"><button>Restore this design</button></form></div></article><?php endforeach ?></div>
